// Vosne's heart is drawn larger than life: Romanée-Conti, La Romanée and La Grande Rue are only a
// couple of hectares between them, so their rows are stretched to stay clickable and labelled.
{
  const clamp01 = t => Math.max(0, Math.min(1, t));
  const ROW = 0.9, RUE = 0.5;
  const sy = y => y + ROW*clamp01((y-6.5)/1.3) + RUE*clamp01((y-7.8)/0.5);
  const mapPts = pts => pts.map(([x,y]) => [x, sy(y)]);
  const vosne = villages.find(v => v.id==="vosne");
  vosne.h += ROW + RUE;
  vosne.base = vosne.base.map(mapPts);
  vosne.town = mapPts(vosne.town);
  climats.filter(c => (c.geo||c.v)==="vosne").forEach(c => { c.s = mapPts(c.s); if(c.lab) c.lab = [c.lab[0], sy(c.lab[1])]; });
}

window.BURG = { producers:P, profiles:PROFILES, villages, climats };
